args.ReplacementContent:
/* ==========================================================================
   Header Container (Fixed Google TV Navigation Bar: #top, .app-header)
   ========================================================================== */
#top,
.app-header {
  position: fixed;
  top: 44px;
  left: 0;
  width: var(--canvas-width, 1920px);
  height: var(--header-height, 84px);
  padding-left: var(--tv-safe-x, 96px);
  padding-right: var(--tv-safe-x, 96px);
  display: flex;
  align-items: center;
  z-index: 100;
  pointer-events: auto;
  transition: opacity 0.3s cubic-bezier(0.2, 0, 0, 1), transform 0.3s cubic-bezier(0.2, 0, 0, 1);
  will-change: opacity, transform;
}

/* Auto-hide transition on vertical scroll (Google TV style) */
.scrolled #top,
body.scrolled #top,
#app.scrolled #top,
.scrolled .app-header,
body.scrolled .app-header,
#app.scrolled .app-header {
  opacity: 0;
  transform: translateY(-20px);
  pointer-events: none;
}

/* Complete hide when entering video player */
#top.header-hidden,
.app-header.header-hidden {
  opacity: 0;
  transform: translateY(-100%);
  pointer-events: none;
}

/* Google TV Top Bar Sub-elements */
.avatar {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: var(--cinema-accent-blue, #8ab4f8);
  color: var(--cinema-bg-base, #0e1014);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  font-weight: 600;
  margin-right: 18px;
  flex-shrink: 0;
  box-sizing: border-box;
  text-decoration: none;
  cursor: pointer;
}

.avatar.focus,
.avatar:focus,
.avatar.focused {
  box-shadow: 0 0 0 4px #fff;
  outline: none;
}

/* Top Pill Navigation Bar Layout */
.pill,
.nav-glass-pill {
  display: inline-flex;
  align-items: center;
  background: var(--cinema-surface-pill, rgba(60, 64, 67, 0.55));
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-radius: var(--radius-pill, 40px);
  padding: 6px;
  margin-right: 18px;
}

.pill.icons {
  padding: 4px;
}

.tab,
.nav-pill-item {
  padding: 12px 28px;
  border-radius: var(--cinema-radius-tab, 30px);
  font-size: 25px;
  font-family: var(--font-family-base);
  color: var(--cinema-text-primary, #e8eaed);
  margin: 0 2px;
  background: transparent;
  border: none;
  cursor: pointer;
  outline: none;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease, color 0.15s ease;
}

.tab.cur,
.tab.active,
.nav-pill-item.active {
  background: var(--cinema-surface-pill-active, rgba(232, 234, 237, 0.18));
}

.tab.focus,
.tab:focus,
.tab.focused,
.nav-pill-item:focus,
.nav-pill-item.focused {
  background: #e8eaed;
  color: #202124;
}

.ico {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--cinema-text-primary, #e8eaed);
  background: transparent;
